from math import pow

def extended_gcd(a, b):
    if a == 0:
        return (b, 0, 1)
    gcd, x1, y1 = extended_gcd(b % a, a)
    x = y1 - (b // a) * x1
    y = x1
    return gcd, x, y

def mod_inverse(a, m):
    gcd, x, _ = extended_gcd(a, m)
    if gcd != 1:
        raise ValueError("Inverse doesn't exist")
    else:
        return x % m

def solve(inputs: dict) -> float:
    remainders = inputs['REMAINDERS']
    moduli = inputs['MODULI']
    total_mod = 1
    for m in moduli:
        total_mod *= m

    result = 0
    for r, m in zip(remainders, moduli):
        p = total_mod // m
        inv_p = mod_inverse(p, m)
        result += r * inv_p * p

    return result % total_mod`
  }
}
